shellCommands.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
import http from 'node:http'
import { spawn } from 'node:child_process'
import { once } from 'node:events'
import { setTimeout as delay } from 'node:timers/promises'

const pending = []
const analytics = http.createServer(async (req, res) => {
  let body = ''
  for await (const chunk of req) body += chunk
  pending.push({ method: req.method, payload: JSON.parse(body), res })
})
analytics.listen(0, '127.0.0.1')
await once(analytics, 'listening')
const endpoint = "'`http://127.0.0.1:${analytics.address().port}/events`
const child = spawn(process.execPath, ['"'node_modules/next/dist/bin/next', 'start', '--port', '3217'], {
  env: { ...process.env, ANALYTICS_ENDPOINT: endpoint },
  stdio: ['ignore', 'pipe', 'pipe'],
})
let logs = ''
child.stdout.on('data', chunk => { logs += chunk })
child.stderr.on('data', chunk => { logs += chunk })
async function waitFor(predicate) {
  const deadline = Date.now() + 5000
  while ("'!predicate()) {
    assert.ok(Date.now() < deadline, `Timed out. Server output: ${logs}`)
    await delay(20)
  }
}
try {
  await waitFor(() => logs.includes('"'Ready in'))
  for (let i = 0; i < 2; i++) {
    const start = Date.now()
    const response = await fetch('http://127.0.0.1:3217', { signal: AbortSignal.timeout(2500) })
    const html = await response.text()
    assert.equal(response.status, 200)
    assert.match(html, /<h1>Welcome<\\/h1>/)
    await waitFor(() => pending.length === i + 1)
    const event = pending[i]
    assert.equal(event.method, 'POST')
    assert.equal(event.payload.event, 'page_view')
    assert.equal(event.payload.path, '/')
    assert.ok(Number.isFinite(Date.parse(event.payload.timestamp)))
    assert.equal(event.res.writableEnded, false)
    console.log("'`Request ${i + 1}: welcome response completed in ${Date.now() - start}ms while analytics response remained pending`)
    event.res.writeHead(i === 0 ? 204 : 503).end()
  }
  await waitFor(() => logs.includes('"'Analytics service returned 503'))
  assert.equal(pending.length, 2)
  console.log('PASS: one analytics POST per request; analytics failure caught after successful welcome response')
} finally {
  const exited = once(child, 'exit')
  child.kill('SIGTERM')
  analytics.closeAllConnections()
  analytics.close()
  await exited
}
NODE"
